// Google Sheets values API: E1:N3, UNFORMATTED_VALUE. No customer rows.
const source = $input.first().json;
const rows = source.values;
if (!Array.isArray(rows) || rows.length < 3) throw new Error('Faltan encabezados o tarifas en E1:N3');
const groups = [
  {service:'excursion', expected:'EXCURSION', cols:[0,1,2], cells:['E3','F3','G3']},
  {service:'traslado', expected:'TRASLADO', cols:[3,4,5], cells:['H3','I3','J3']},
  {service:'auto', expected:'AUTO', cols:[6,8,9], cells:['K3','M3','N3']},
];
const rates = groups.map(g => {
  const prices = g.cols.map(i => {
    if (String(rows[0][i] || '').trim().toUpperCase() !== g.expected)
      throw new Error('Cambió el encabezado de ' + g.service + '. Revisar mapeo.');
    const n = rows[2][i];
    if (typeof n !== 'number' || !Number.isFinite(n) || n <= 0)
      throw new Error('Tarifa inválida para ' + g.service + ': se requiere número positivo.');
    return n;
  });
  if (!(prices[0] >= prices[1] && prices[1] >= prices[2]))
    throw new Error('Orden de precios inesperado en ' + g.service);
  return {service:g.service, unit:'km', currency:'ARS',
    green_reference:prices[0], yellow_standard:prices[1], red_floor:prices[2],
    source_cells:g.cells, default_level:'yellow',
    discount_policy:'Solo para varios viajes, hasta el piso rojo, con aprobación humana',
    green_policy:'Pendiente definir cuándo aplicar',
    availability:'not_checked', validity:'not_confirmed'};
});
return [{json:{mode:'preview_only', requires_human_approval:true, can_send:false,
  source:{spreadsheet_id:'1W55J03Uy1sY15Wj649_JDslyg1vCiBNHDpB5pvjTMS8',
    sheet:'TRANSPORTE-ROMA-2026', range:'E1:N3', read_at:new Date().toISOString()},
  rates,
  warnings:['No se consulta disponibilidad ni se prepara un presupuesto final.',
    'L3 (UBER XL) no se importa: contiene texto y debe definirse por separado.',
    'Los colores son niveles comerciales, no temporadas.']
}}];
